<?php

namespace RayanLevert\Model\Tests\Model;

use PDO;
use PHPUnit\Framework\Attributes\Test;
use RayanLevert\Model\Connections\Postgres;
use RayanLevert\Model\Queries\Postgres as QueriesPostgres;
use RayanLevert\Model\State;
use RayanLevert\Model\Tests\Fixtures\User;

/**
 * This class is used to test with a **real** PostgreSQL database all the queries generated by the Model class
 *
 * Assuring the database *model* is created and table *user* as well
 *
 * - id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY
 * - first_name character varying(45) NOT NULL
 * - last_name character varying(45) NOT NULL
 */
class PostgresTest extends \RayanLevert\Model\Tests\TransactionTestCase
{
    #[Test]
    public function createSaveAndDeleteSuccessfully(): void
    {
        $model = new User();

        $model->firstName = 'John';
        $model->lastName  = 'Doe';

        $this->assertSame(State::TRANSIANT, $model->state);

        // No exception thrown
        $model->create();
        $id = $model->id;

        $this->assertSame(State::PERSISTENT, $model->state);

        // The AutoIncrement column is assigned to the model
        $this->assertNotNull($model->id);
        $this->assertNotSame(0, $model->id);

        // Select afterwards
        $oStatement = $this->dataObject->pdo->prepare('SELECT * FROM "user"');
        $this->assertTrue($oStatement->execute());
        $this->assertSame(
            ['id' => $id, 'first_name' => 'John', 'last_name' => 'Doe'],
            $oStatement->fetch(PDO::FETCH_ASSOC)
        );

        // From the find method as well
        $this->assertNotNull($oModel = $model->findFirstByPrimaryKey($id));
        $this->assertSame('John', $oModel->firstName);
        $this->assertSame('Doe', $oModel->lastName);
        $this->assertSame($id, $oModel->id);

        $model->firstName = 'Jane';
        $model->lastName  = 'Smith';

        // No exception thrown
        $model->save();

        $this->assertSame(State::PERSISTENT, $model->state);

        // The AutoIncrement column is not changed
        $this->assertSame($id, $model->id);

        // Select afterwards
        $oStatement = $this->dataObject->pdo->prepare('SELECT * FROM "user"');

        $this->assertTrue($oStatement->execute());
        $this->assertSame(['id' => $model->id, 'first_name' => 'Jane', 'last_name' => 'Smith'], $oStatement->fetch(PDO::FETCH_ASSOC));

        $model->delete();

        // Select afterwards
        $oStatement = $this->dataObject->pdo->prepare('SELECT * FROM "user"');

        $this->assertTrue($oStatement->execute());
        $this->assertEmpty($oStatement->fetch(PDO::FETCH_ASSOC));
        $this->assertSame(0, $oStatement->rowCount());

        $this->assertSame(State::DETACHED, $model->state);
    }

    /** Returns a working Connection to the postgres database */
    protected function getConnection(): Postgres
    {
        return new Postgres('postgres', 'postgres', 'postgres-password', ['dbname' => 'postgres']);
    }

    /** Returns a working Queries object to the postgres database */
    protected function getQueries(): QueriesPostgres
    {
        return new QueriesPostgres();
    }
}
